    blue = [(y, x) for y in range(9, 41) for x in range(13, 51)
            if board[y][x] == 11]
    if not blue:
        return
    ys = sorted(set(y for y, x in blue))
    groups = []
    for y in ys:
        if not groups or y > groups[-1][-1] + 1:
            groups.append([y])
        else:
            groups[-1].append(y)
    # Two overlapping/adjacent figures have rows 0-3 and 4-7.
    if len(ys) >= 8:
        y0 = ys[0]
        upper = [(y, x) for y, x in blue if y < y0 + 4]
        lower = [(y, x) for y, x in blue if y >= y0 + 4]
        for y, x in upper:
            board[y][x] = 5
        if lower:
            y0 = min(y for y, x in lower)
            xs = [x for y, x in lower if y == y0]
            x0, x1 = min(xs), max(xs)
            for y in range(y0, y0 + 4):
                for x in range(x0, x1 + 1):
                    board[y][x] = 11
    else:
        y0 = min(y for y, x in blue)
        x1 = max(x for y, x in blue)
        x0 = x1 - 3
